// Autorização conferida pelo sensei. A solicitação não verifica parentesco.
const DojoGuardian=(()=>{
 const version='2026-10-29.1',contact='personalandrecordeiro@gmail.com';
 const consent='Autorizo o uso do San Dojo pelo aluno sob minha responsabilidade e o tratamento dos dados necessários à conta, ao salvamento do progresso e ao acompanhamento pelo sensei, conforme a política de privacidade. Sei que posso retirar esta autorização e pedir exclusão. Esta autorização não inclui publicidade personalizada, divulgação de imagem ou gravação de voz.';
 const originalAccountPage=accountPage;
 function requestForm(){return `<form id="guardian-request" class="guardian-form"><h2>Autorização do responsável</h2><p>Esta área deve ser preenchida por mãe, pai ou responsável legal adulto, usando sua própria conta Google. Cada conta acompanha um aluno nesta versão.</p><label>Seu nome, como responsável<input name="guardian_name" required minlength="3" maxlength="80" autocomplete="name"></label><label>Vínculo com o aluno<select name="relationship" required><option value="">Selecione</option><option value="mae">Mãe</option><option value="pai">Pai</option><option value="responsavel_legal">Responsável legal</option></select></label><label>Como chamar o aluno<input name="learner_alias" required minlength="2" maxlength="40" autocomplete="off" placeholder="Primeiro nome ou apelido"></label><p class="week-note">Contato para retorno: o e-mail da conta Google usada na entrada. Não envie documentos, senhas, data de nascimento ou informações de saúde.</p><div class="guardian-consent"><h3>Leia antes de autorizar</h3><p>${consent}</p><a href="privacidade.html" target="_blank" rel="noopener">Ler a política de privacidade</a><label class="guardian-check"><input type="checkbox" name="confirm" required> Sou responsável legal adulto pelo aluno, li o texto acima e dou esta autorização específica.</label></div><p>O sensei confirmará sua identidade, o vínculo e a autorização no dojo ou por um contato já conhecido. O formulário sozinho não libera as atividades.</p><button class="primary" type="submit">Solicitar liberação ao sensei →</button><p role="status" id="guardian-status"></p></form>`;}
 function actions(){const A=DojoAccounts,open=['pending','processing'].includes(A.erasure?.status);return `<div class="info-panel guardian-panel"><h2>Privacidade e responsável</h2><p><a href="privacidade.html">Consultar a política de privacidade</a> · <a href="mailto:${contact}?subject=Privacidade%20San%20Dojo">Falar com André</a></p>${A.isAdmin?'<p>A conta administradora permanece liberada para gerenciar o dojo. Os pedidos dos responsáveis ficam no painel abaixo.</p><button class="outline" data-privacy-queue>Ver autorizações e pedidos →</button><div id="privacy-queue"></div>':open?`<div class="learning-callout"><h3>Pedido de exclusão registrado</h3><p>Solicitado em ${date(A.erasure.requested_at)}. Situação: ${A.erasure.status==='processing'?'em atendimento pelo sensei':'aguardando atendimento'}. As atividades estão pausadas. O registro do pedido não significa que os dados já foram apagados; André conferirá a identidade e tratará a exclusão.</p><button class="outline" data-cancel-erasure>Cancelar meu pedido de exclusão</button><p class="week-note">Cancelar não recupera dados já excluídos nem reativa a autorização retirada.</p></div>`:`${A.guardian&&A.guardian.status!=='withdrawn'?'<button class="outline" data-privacy-confirm="withdraw">Retirar autorização e pausar atividades</button>':''}<button class="text-button danger" data-privacy-confirm="erasure">Solicitar exclusão da conta e dos dados</button><div id="privacy-confirm"></div>`}<p role="status" id="privacy-status"></p></div>`;}
 function date(value){return new Date(value).toLocaleDateString('pt-BR');}
 accountPage=function(){const A=DojoAccounts;if(!A.user)return originalAccountPage().replace('Entre com sua conta Google ou Apple. No primeiro acesso, seu cadastro de aluno é criado automaticamente.','Responsável: entre com sua própria conta Google para acompanhar o aluno. O acesso às atividades será liberado após a conferência do sensei.').replace('Crianças devem acessar com acompanhamento do responsável.','Criança: peça a um responsável para fazer a entrada. Não use uma conta infantil para preencher a autorização.');if(A.isAdmin)return originalAccountPage()+actions();const g=A.guardian,open=['pending','processing'].includes(A.erasure?.status);let body='';if(!A.error&&!open){if(!A.active)body='<p>O acesso foi pausado pelo sensei. Fale com André antes de pedir nova liberação.</p>';else if(g?.status==='approved')body=`<div class="info-panel"><h2>Autorização conferida</h2><p>Aluno: ${esc(g.learner_alias)}. Responsável: ${esc(g.guardian_name)}.</p><p>Conferência registrada pelo sensei em ${date(g.reviewed_at)}. Versão da autorização: ${esc(g.consent_version)}.</p></div>`;else if(g?.status==='pending')body=`<div class="info-panel"><h2>Aguardando conferência do sensei</h2><p>Solicitação de ${esc(g.guardian_name)} para ${esc(g.learner_alias)}, enviada em ${date(g.requested_at)}.</p><p>Fale com André no dojo ou por um contato já conhecido para confirmar a autorização. As atividades e os materiais privados aguardam essa conferência.</p><button class="outline" data-refresh-privacy>Conferir liberação</button></div>`;else body=`<div class="info-panel"><h2>${g?.status==='withdrawn'?'Autorização retirada':g?.status==='rejected'?'Converse com o sensei para revisar a solicitação':'Antes da primeira atividade'}</h2>${requestForm()}</div>`;}return originalAccountPage()+body+actions();};
 async function queue(){const panel=document.getElementById('privacy-queue');if(!panel)return;panel.textContent='Carregando…';try{const data=await DojoAccounts.privacyQueue(),students=await DojoAccounts.students(),profiles=Object.fromEntries(students.map(s=>[s.id,s]));panel.innerHTML=`<h3>Autorizações aguardando conferência</h3><p>Confira com o responsável por um meio que você já conhece. Não aprove apenas porque o formulário foi preenchido. Registre somente o necessário; não copie documentos ou informações sensíveis.</p>${data.guardians.filter(g=>g.status==='pending').map(g=>`<form class="guardian-review" data-user="${esc(g.user_id)}" data-revision="${g.revision}"><h4>${esc(g.learner_alias)}</h4><p>Responsável informado: ${esc(g.guardian_name)} · ${esc({mae:'Mãe',pai:'Pai',responsavel_legal:'Responsável legal'}[g.relationship])}</p><p>Conta: ${esc(profiles[g.user_id]?.email||'Conta cadastrada')} · ${date(g.requested_at)}</p><p>Autorização versão ${esc(g.consent_version)}.</p><label>Como você conferiu?<select name="method" required><option value="">Selecione</option><option value="presencial">Presencialmente no dojo</option><option value="contato_conhecido">Contato do responsável já conhecido pelo dojo</option></select></label><label>Registro breve da conferência<textarea name="note" required minlength="8" maxlength="300" placeholder="Ex.: autorização confirmada com o responsável no dojo."></textarea></label><label class="guardian-check"><input name="confirm" type="checkbox" required> Conferi a identidade, o vínculo e a manifestação do responsável por um meio conhecido.</label><div class="guardian-buttons"><button class="primary" type="submit" value="approve">Confirmar autorização</button><button class="outline" type="submit" value="reject">Devolver para revisão</button></div><p role="status"></p></form>`).join('')||'<p>Nenhuma autorização aguardando conferência.</p>'}<h3>Pedidos de exclusão</h3><p>Confira a identidade e a legitimidade do pedido antes de apagar dados. Marcar atendimento não exclui a conta. A exclusão definitiva é feita no Supabase, depois da conferência; não remova a conta administradora.</p>${data.requests.map(r=>`<article class="guardian-review"><h4>${esc(profiles[r.user_id]?.display_name||'Conta do aluno')}</h4><p>${esc(profiles[r.user_id]?.email||'')} · ${date(r.requested_at)} · ${r.status==='processing'?'Em atendimento':'Aguardando atendimento'}</p><p>Identificador da conta: <code>${esc(r.user_id)}</code></p>${r.status==='pending'?`<button class="outline" data-process-erasure="${esc(r.user_id)}">Marcar em atendimento</button>`:''}</article>`).join('')||'<p>Nenhum pedido de exclusão pendente.</p>'}<h3>Autorizações já analisadas</h3>${data.guardians.filter(g=>g.status!=='pending').map(g=>`<p>${esc(g.learner_alias)} · ${esc(g.guardian_name)} · ${{approved:'Conferida',rejected:'Devolvida para revisão',withdrawn:'Retirada'}[g.status]}</p>`).join('')||'<p>Nenhuma autorização analisada.</p>'}`;}catch{panel.textContent='Não foi possível carregar os pedidos. Tente novamente.';}}
 function resetLocal(){try{if(DojoAccounts.user)localStorage.removeItem('san-dojo-user-'+DojoAccounts.user.id);}catch{}}
 document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='guardian-request'&&!form.matches('.guardian-review'))return;event.preventDefault();const button=event.submitter;form.querySelectorAll('button').forEach(b=>b.disabled=true);const status=form.querySelector('[role="status"]');status.textContent='Enviando…';try{const data=new FormData(form);if(form.id==='guardian-request'){await DojoAccounts.privacyRpc('dojo_request_guardian',{p_name:String(data.get('guardian_name')),p_relationship:String(data.get('relationship')),p_alias:String(data.get('learner_alias')),p_version:version,p_confirm:data.get('confirm')==='on'});location.reload();}else{await DojoAccounts.privacyRpc('dojo_review_guardian',{p_user:form.dataset.user,p_revision:Number(form.dataset.revision),p_approve:button?.value==='approve',p_method:String(data.get('method')),p_note:String(data.get('note')),p_confirm:data.get('confirm')==='on'});await queue();}}catch{status.textContent='Não foi possível registrar. Confira os campos, atualize a página e tente novamente.';form.querySelectorAll('button').forEach(b=>b.disabled=false);}});
 document.addEventListener('click',async event=>{const e=event.target.closest('button');if(!e)return;const status=document.getElementById('privacy-status');if(e.hasAttribute('data-privacy-queue')){await queue();return;}if(e.hasAttribute('data-refresh-privacy')){location.reload();return;}if(e.dataset.privacyConfirm){const kind=e.dataset.privacyConfirm;document.getElementById('privacy-confirm').innerHTML=`<div class="guardian-consent"><h3>${kind==='withdraw'?'Retirar autorização?':'Solicitar exclusão?'}</h3><p>${kind==='withdraw'?'As atividades e o acesso aos materiais privados serão pausados. Os dados existentes permanecem guardados até um pedido de exclusão. Uma nova liberação exige nova conferência.':'As atividades serão pausadas e o pedido ficará registrado para André. A exclusão será tratada após conferência; este botão não apaga os dados imediatamente. Se a exclusão for concluída, progresso e aprovações não poderão ser recuperados.'}</p><button class="outline danger" data-execute-privacy="${kind}">${kind==='withdraw'?'Confirmar retirada':'Confirmar pedido de exclusão'}</button><button class="text-button" data-dismiss-privacy>Voltar</button></div>`;return;}if(e.hasAttribute('data-dismiss-privacy')){document.getElementById('privacy-confirm').innerHTML='';return;}if(e.dataset.executePrivacy||e.hasAttribute('data-cancel-erasure')||e.dataset.processErasure){e.disabled=true;try{if(e.dataset.processErasure){await DojoAccounts.privacyRpc('dojo_process_erasure',{p_user:e.dataset.processErasure});await queue();return;}if(e.hasAttribute('data-cancel-erasure'))await DojoAccounts.privacyRpc('dojo_cancel_erasure');else{await DojoAccounts.flush();await DojoAccounts.privacyRpc(e.dataset.executePrivacy==='withdraw'?'dojo_withdraw_guardian':'dojo_request_erasure',e.dataset.executePrivacy==='withdraw'?{}:{p_confirm:true});resetLocal();}location.reload();}catch{if(status)status.textContent='Não foi possível concluir. Tente novamente ou fale com André.';e.disabled=false;}}});
 return {version,consent};
})();
